/**
 * The MCP and Anthropic spelling of `parameters`. Give one or the other, not both.
 * @nullable
 */
export type ClientFunctionRequestInputSchema = { [key: string]: unknown } | null;

/**
 * JSON Schema for the arguments. Omit for an action that takes none.
 * @nullable
 */
export type ClientFunctionRequestParameters = { [key: string]: unknown } | null;

/**
 * The function object from the OpenAI tools format.
 */
export interface ClientFunctionRequest {
  /**
   * What the action does, written for the model. An action without one can only be guessed at from its name. The 1024 ceiling is OpenAI's own limit on `tools[].function.description`, not a number chosen here: over it the upstream call fails with `string_above_max_length`, and refusing at submission is the clearer of the two places to refuse. It was 500, which ran out at about six enumerated entries — an action that must list what it accepts had nowhere to put the list.
   * @minLength 1
   * @maxLength 1024
   */
  description: string;
  /**
   * The MCP and Anthropic spelling of `parameters`. Give one or the other, not both.
   * @nullable
   */
  inputSchema?: ClientFunctionRequestInputSchema;
  /**
   * @minLength 1
   * @maxLength 64
   */
  name: string;
  /**
   * JSON Schema for the arguments. Omit for an action that takes none.
   * @nullable
   */
  parameters?: ClientFunctionRequestParameters;
}

/**
 * Only functions are supported.
 */
export type ClientActionRequestType =
  (typeof ClientActionRequestType)[keyof typeof ClientActionRequestType];

export const ClientActionRequestType = {
  function: "function",
} as const;

/**
 * The shape of a tool in the OpenAI Chat Completions API, plus `readOnly` and `timeoutMs`.
 */
export interface ClientActionRequest {
  function: ClientFunctionRequest;
  /** True when the action changes nothing outside the client. Anything else goes through this conversation's approval before it runs. */
  readOnly: boolean;
  /**
   * How long the assistant should wait for this action. Omit for the default; longer values are capped.
   * @minimum 0
   */
  timeoutMs?: number;
  /** Only functions are supported. */
  type?: ClientActionRequestType;
}

/**
 * Which client this is and what it can do, so the assistant can ask it to do those things
 * while it answers. What the operator is looking at travels as `data-*` parts on the message.
 *
 * Send `actions` only when they differ from the last message on this conversation. Sending the
 * block without `actions` keeps whatever was declared before.
 */
export interface ClientContextRequest {
  /**
   * The actions on offer right now.
   *
   * Omit it when nothing changed since the last message. Send `[]` to say there is nothing
   * on offer — those are different: a client that moves off the page it was attached to has
   * to be able to say so, or the assistant keeps calling actions that no longer make sense.
   * @maxItems 32
   * @nullable
   */
  actions?: ClientActionRequest[] | null;
  /**
   * Identifies this client while it stays open. Any stable string; one per tab or process.
   * @minLength 1
   * @maxLength 128
   */
  clientId: string;
  /**
   * How the client calls itself, for example "Leaflow console (web)".
   * @maxLength 64
   */
  label?: string;
}

/**
 * For `data-*` parts. Any object; its keys reach the assistant as they are.
 * @nullable
 */
export type MessagePartData = { [key: string]: unknown } | null;

/**
 * One piece of a message. `type` says which of the fields below carries it:
 *
 * - `text` — the words, in `text`
 * - `file` — an attachment uploaded earlier, by id in `attachmentId`
 * - `data-<something>` — context from the client, in `data`. The name after `data-` is yours;
 *   it is shown to the assistant so it can tell one kind of block from another.
 *
 * Order matters: an attachment belongs where it was written, not at the end.
 */
export interface MessagePart {
  /**
   * For `file` parts. The attachment must have been uploaded and not yet bound to another message.
   * @nullable
   */
  attachmentId?: string | null;
  /**
   * For `data-*` parts. Any object; its keys reach the assistant as they are.
   * @nullable
   */
  data?: MessagePartData;
  /**
   * For `text` parts.
   * @nullable
   */
  text?: string | null;
  /**
   * @minLength 1
   * @maxLength 64
   */
  type: string;
}

export interface SendMessageRequestBody {
  client?: ClientContextRequest;
  /**
   * The message, in the order it was written. A message with nothing but text is a single
   * text part; that is the ordinary case and nothing else is required.
   * @minItems 1
   */
  parts: MessagePart[];
}

